71	/**
72	 * Walks frames starting at the beginning of `bytes`, which sit at `baseOffset`
73	 * in the file. Returns the decoded frames, the file offset just after the last
74	 * good one, and `tail` when the bytes after that are not a complete frame.
75	 */
76	export function scanFrames(bytes, baseOffset = 0) {
77	  const frames = [];
78	  let pos = 0;
79	  let tail = null;
80	  while (pos < bytes.length) {
81	    const decoded = decodeFrameAt(bytes, pos);
82	    if (!decoded.ok) {
83	      if (decoded.reason !== 'partial') {
84	        throw new CorruptLogError(
85	          `corrupt record at offset ${baseOffset + pos} (${decoded.reason})`,
86	          { offset: baseOffset + pos, reason: decoded.reason },
87	        );
88	      }
89	      tail = { offset: baseOffset + pos, reason: decoded.reason, bytes: bytes.length - pos };
90	      break;
91	    }
92	    frames.push({ offset: baseOffset + pos, size: decoded.next - pos, record: decoded.record });
93	    pos = decoded.next;
94	  }
95	  return { frames, end: baseOffset + pos, tail };
96	}
