95	// Keeps written bytes in this process until sync(), like a page cache. A process
96	// killed at a failpoint therefore loses them, as a machine losing power would.
97	class PowerLossFileOps extends RealFileOps {
98	  constructor() {
99	    super();
100	    this.pending = new Map();
101	  }
102	
103	  size(file) {
104	    let size = super.size(file);
105	    for (const { position, bytes } of this.pending.get(file) ?? []) {
106	      size = Math.max(size, position + bytes.length);
107	    }
108	    return size;
109	  }
110	
111	  read(file, offset = 0, length = Infinity) {
112	    const writes = this.pending.get(file);
113	    if (!writes?.length) return super.read(file, offset, length);
114	    const image = Buffer.alloc(this.size(file));
115	    super.read(file).copy(image);
116	    for (const { position, bytes } of writes) bytes.copy(image, position);
117	    return image.subarray(offset, Math.min(image.length, offset + length));
118	  }
119	
120	  create(file, options) {
121	    super.create(file, options);
122	    this.pending.delete(file);
123	  }
124	
125	  writeAt(file, bytes, position) {
126	    if (!this.pending.has(file)) this.pending.set(file, []);
127	    this.pending.get(file).push({ position, bytes: Buffer.from(bytes) });
128	  }
129	
130	  sync(file) {
131	    for (const { position, bytes } of this.pending.get(file) ?? []) {
132	      super.writeAt(file, bytes, position);
133	    }
134	    this.pending.delete(file);
135	    super.sync(file);
136	  }
137	
138	  truncate(file, length) {
139	    super.truncate(file, length);
140	    const kept = (this.pending.get(file) ?? []).filter((w) => w.position + w.bytes.length <= length);
141	    this.pending.set(file, kept);
142	  }
143	
144	  rename(from, to) {
145	    super.rename(from, to);
146	    const moving = this.pending.get(from);
147	    this.pending.delete(from);
148	    if (moving) this.pending.set(to, moving);
149	    else this.pending.delete(to);
150	  }
151	
152	  unlink(file) {
153	    super.unlink(file);
154	    this.pending.delete(file);
155	  }
156	}
157	
158	export function createFileOps() {
159	  return process.env.WALQ_SIMULATE_POWER_LOSS === '1' ? new PowerLossFileOps() : new RealFileOps();
160	}
