1	// Store: the replayed state plus the rules for reading and writing the log.
2	// Every read of shared state and every write happens inside withLock(), which
3	// first brings this process up to date with whatever other processes wrote.
4	
5	import path from 'node:path';
6	import { compactLog } from './compactor.mjs';
7	import { QueueClosedError } from './errors.mjs';
8	import { FORMAT_VERSION, HEADER_SIZE } from './frame.mjs';
9	import { createFileOps, ensureDir } from './fsops.mjs';
10	import { acquireLock } from './lock.mjs';
11	import { createLogger } from './logger.mjs';
12	import { applyRecord, createState } from './state.mjs';
13	import { Wal } from './wal.mjs';
14	
15	export const WAL_FILE = 'wal.log';
16	export const LOCK_FILE = 'queue.lock';
17	
18	const log = createLogger('store');
19	
20	export class Store {
21	  constructor(dir, config) {
22	    this.dir = dir;
23	    this.config = config;
24	    this.clock = config.clock;
25	    this.ops = createFileOps();
26	    this.wal = new Wal(path.join(dir, WAL_FILE), this.ops);
27	    this.lockPath = path.join(dir, LOCK_FILE);
28	    this.state = createState();
29	    this.generation = null;
30	    this.offset = HEADER_SIZE;
31	    this.snapshotBytes = 0;
32	    this.tornTailsDropped = 0;
33	    this.lastCompactionError = null;
34	    this.closed = false;
35	    this.holdingLock = false;
36	  }
37	
38	  open() {
39	    ensureDir(this.dir);
40	    this.#locked(() => {
41	      if (!this.wal.exists()) this.wal.create();
42	      this.catchUp();
43	    });
44	  }
45	
46	  close() {
47	    this.closed = true;
48	  }
49	
50	  #locked(fn) {
51	    if (this.holdingLock) throw new Error('queue lock is not reentrant');
52	    const release = acquireLock(this.lockPath, { timeoutMs: this.config.lockTimeoutMs });
53	    this.holdingLock = true;
54	    try {
55	      return fn();
56	    } finally {
57	      this.holdingLock = false;
58	      release();
59	    }
60	  }
61	
62	  withLock(fn) {
63	    if (this.closed) throw new QueueClosedError();
64	    return this.#locked(() => {
65	      this.catchUp();
66	      return fn();
67	    });
68	  }
69	
70	  /** Brings this.state up to date with the log without doing anything else. */
71	  refresh() {
72	    this.withLock(() => {});
73	  }
74	
75	  catchUp() {
76	    const header = this.wal.readHeader();
77	    if (this.generation === null || this.ops.size(this.wal.file) < this.offset) {
78	      this.state = createState();
79	      this.offset = HEADER_SIZE;
80	      this.generation = header.generation;
81	    }
82	
83	    const { frames, end, tail } = this.wal.scanFrom(this.offset);
84	    for (const frame of frames) {
85	      applyRecord(this.state, frame.record, this.clock);
86	      if (frame.record.t === 'snapshot') this.snapshotBytes = frame.size;
87	    }
88	    this.offset = end;
89	
90	    if (tail) {
91	      this.tornTailsDropped += 1;
92	      log.warn('ignored incomplete tail', { offset: end, reason: tail.reason, bytes: tail.bytes });
93	    }
94	  }
95	
96	  /** Must be called inside withLock(). */
97	  append(records, options) {
98	    this.offset = this.wal.append(records, options);
99	    for (const record of records) applyRecord(this.state, record, this.clock);
100	  }
101	
102	  /** Must be called inside withLock(). */
103	  compact() {
104	    const bytesBefore = this.offset;
105	    const { snapshot, generation, size } = compactLog({
106	      wal: this.wal,
107	      ops: this.ops,
108	      state: this.state,
109	      generation: this.generation,
110	      now: this.clock.now(),
111	      config: this.config,
112	    });
113	    this.state = createState();
114	    applyRecord(this.state, snapshot);
115	    this.generation = generation;
116	    this.offset = size;
117	    this.snapshotBytes = size - HEADER_SIZE;
118	    log.info('compacted', { generation, bytesBefore, bytesAfter: size });
119	    return { generation, bytesBefore, bytesAfter: size, jobs: this.state.jobs.size };
120	  }
121	
122	  /**
123	   * Compacts when the log has outgrown the threshold. A failure here must not
124	   * fail the operation that triggered it, because that operation has committed.
125	   */
126	  maybeCompact() {
127	    const threshold = this.config.compactAfterBytes;
128	    if (!threshold) return;
129	    if (this.offset < threshold) return;
130	    try {
131	      this.compact();
132	      this.lastCompactionError = null;
133	    } catch (err) {
134	      this.lastCompactionError = err;
135	      log.warn('compaction failed', { error: err.message });
136	    }
137	  }
138	
139	  describe() {
140	    return {
141	      format: FORMAT_VERSION,
142	      generation: this.generation,
143	      logBytes: this.offset,
144	      tornTailsDropped: this.tornTailsDropped,
145	      lastCompactionError: this.lastCompactionError?.message ?? null,
146	    };
147	  }
148	}
