26	      type: rec.type,
27	      payload: rec.payload,
28	      key: rec.key ?? null,
29	      priority: rec.priority ?? 0,
30	      status: 'ready',
31	      attempts: 0,
32	      fence: 0,
33	      maxAttempts: rec.maxAttempts,
34	      availableAt: rec.availableAt,
35	      lease: null,
36	      result: null,
