70	export function hit(name, context = {}) {
71	  callbacks.get(name)?.(context);
72	  for (const rule of rules) {
73	    if (rule.name !== name) continue;
74	    if (rule.type !== null && rule.type !== context.type) continue;
75	    const seen = (counts.get(rule.key) ?? 0) + 1;
76	    counts.set(rule.key, seen);
77	    if (seen === rule.nth) fire(rule);
78	  }
79	}
