1	// JobRunner: the loop a worker process runs. Claim a job, run its handler with a
2	// heartbeat going, then record the outcome.
3	
4	import { sleep } from '../clock.mjs';
5	import { StaleLeaseError, UnknownJobError, WalqError } from '../errors.mjs';
6	import { hit } from '../failpoints.mjs';
7	import { JOB_COMPLETED, JOB_FAILED, JOB_FENCED, JOB_STARTED, WORKER_ERROR } from './protocol.mjs';
8	import { runWithTimeout } from './registry.mjs';
9	
10	export class JobRunner {
11	  constructor({ queue, workerId, handlers, leaseMs, heartbeatMs, pollMs = 20, types = null, emit = () => {} }) {
12	    this.queue = queue;
13	    this.workerId = workerId;
14	    this.handlers = handlers;
15	    this.leaseMs = leaseMs ?? queue.config.leaseMs;
16	    this.heartbeatMs = heartbeatMs ?? Math.max(10, Math.floor(this.leaseMs / 3));
17	    this.pollMs = pollMs;
18	    this.types = types;
19	    this.emit = emit;
20	    this.stopping = false;
21	  }
22	
23	  stop() {
24	    this.stopping = true;
25	  }
26	
27	  async run() {
28	    while (!this.stopping) {
29	      const job = this.#claimNext();
30	      if (job) await this.execute(job);
31	      else await sleep(this.pollMs);
32	    }
33	  }
34	
35	  #claimNext() {
36	    try {
37	      return this.queue.claim(this.workerId, { leaseMs: this.leaseMs, types: this.types });
38	    } catch (err) {
39	      if (!(err instanceof WalqError)) throw err;
40	      this.emit({ kind: WORKER_ERROR, error: err.message });
41	      return null;
42	    }
43	  }
44	
45	  async execute(job) {
46	    const { id, token } = job;
47	    hit('job.before-handler', { id });
48	    this.emit({ kind: JOB_STARTED, id, attempt: job.attempt, token });
49	
50	    const abort = new AbortController();
51	    const beat = setInterval(() => {
52	      try {
53	        this.queue.heartbeat(id, token, { leaseMs: this.leaseMs });
54	      } catch (err) {
55	        if (err instanceof StaleLeaseError) {
56	          clearInterval(beat);
57	          abort.abort();
58	        } else {
59	          this.emit({ kind: WORKER_ERROR, error: err.message });
60	        }
61	      }
62	    }, this.heartbeatMs);
63	
64	    let result;
65	    try {
66	      const handler = this.handlers.get(job.type);
67	      if (!handler) throw new Error(`no handler for job type ${job.type}`);
68	      result = await runWithTimeout(
69	        handler,
70	        job.payload,
71	        { id, attempt: job.attempt, token, workerId: this.workerId, signal: abort.signal },
72	        abort,
73	      );
74	    } catch (err) {
75	      clearInterval(beat);
76	      await this.#report(id, () => this.queue.fail(id, token, err), JOB_FAILED, err);
77	      return;
78	    }
79	
80	    clearInterval(beat);
81	    hit('job.after-handler', { id });
82	    await this.#report(id, () => this.queue.complete(id, token, result), JOB_COMPLETED);
83	    hit('job.after-complete', { id });
84	  }
85	
86	  // A fenced worker has lost the job to someone else. That is an expected end for
87	  // this attempt, not an error.
88	  async #report(id, call, kind, cause) {
89	    try {
90	      call();
91	      this.emit({ kind, id, error: cause?.message });
92	    } catch (err) {
93	      if (err instanceof StaleLeaseError || err instanceof UnknownJobError) {
94	        this.emit({ kind: JOB_FENCED, id });
95	      } else {
96	        this.emit({ kind: WORKER_ERROR, id, error: err.message });
97	      }
98	    }
99	  }
100	}
