1	// WorkerPool: starts worker processes, replaces the ones that die, and returns
2	// jobs to the queue when their lease runs out.
3	
4	import { fork } from 'node:child_process';
5	import { EventEmitter } from 'node:events';
6	import { fileURLToPath } from 'node:url';
7	import { sleep } from '../clock.mjs';
8	import { createLogger } from '../logger.mjs';
9	import { openQueue } from '../queue.mjs';
10	import { STOP } from './protocol.mjs';
11	
12	const CHILD_PATH = fileURLToPath(new URL('./child.mjs', import.meta.url));
13	const STOP_GRACE_MS = 2_000;
14	
15	const log = createLogger('pool');
16	
17	export class WorkerPool extends EventEmitter {
18	  constructor({
19	    dir,
20	    handlers,
21	    size = 2,
22	    leaseMs = 30_000,
23	    heartbeatMs,
24	    pollMs = 20,
25	    reapMs,
26	    types = null,
27	    env = {},
28	    queue = {},
29	    maxRespawns = 100,
30	  }) {
31	    super();
32	    this.options = { dir, handlers, leaseMs, heartbeatMs, pollMs, types, queue };
33	    this.size = size;
34	    this.reapMs = reapMs ?? Math.max(20, Math.floor(leaseMs / 2));
35	    this.env = env;
36	    this.maxRespawns = maxRespawns;
37	    this.children = new Map();
38	    this.incarnation = 0;
39	    this.respawns = 0;
40	    this.stopping = false;
41	    this.reaper = null;
42	    this.queue = null;
43	  }
44	
45	  start() {
46	    this.queue = openQueue(this.options.dir, this.options.queue);
47	    for (let i = 0; i < this.size; i += 1) this.#spawn();
48	    this.reaper = setInterval(() => this.#reap(), this.reapMs);
49	    return this;
50	  }
51	
52	  #reap() {
53	    try {
54	      this.queue.reapExpired();
55	    } catch (err) {
56	      this.emit('error-event', err);
57	    }
58	  }
59	
60	  #spawn() {
61	    this.incarnation += 1;
62	    const workerId = `w${this.incarnation}`;
63	    const child = fork(CHILD_PATH, [JSON.stringify({ ...this.options, workerId })], {
64	      env: { ...process.env, ...this.env },
65	      silent: true,
66	      windowsHide: true,
67	    });
68	    child.stdout.resume();
69	    child.stderr.on('data', (chunk) => this.emit('stderr', chunk.toString()));
70	    child.on('message', (message) => this.emit('message', message));
71	    child.on('error', (err) => this.emit('error-event', err));
72	    child.on('exit', (code, signal) => this.#onExit(workerId, code, signal));
73	    this.children.set(workerId, child);
74	  }
75	
76	  #onExit(workerId, code, signal) {
77	    this.children.delete(workerId);
78	    this.emit('exit', { workerId, code, signal });
79	    log.info('worker exited', { workerId, code, signal, stopping: this.stopping });
80	    if (this.stopping) return;
81	    if (this.respawns < this.maxRespawns) {
82	      this.respawns += 1;
83	      this.#spawn();
84	    }
85	  }
86	
87	  /** Resolves once no job is ready or leased. Rejects if that takes too long. */
88	  async drain({ timeoutMs = 60_000 } = {}) {
89	    const deadline = performance.now() + timeoutMs;
90	    for (;;) {
91	      const { ready, leased } = this.queue.stats();
92	      if (ready === 0 && leased === 0) return;
93	      if (performance.now() >= deadline) {
94	        throw new Error(`drain timed out with ${ready} ready and ${leased} leased jobs`);
95	      }
96	      await sleep(25);
97	    }
98	  }
99	
100	  /** Stops every worker and waits for them to go. */
101	  async stop() {
102	    this.stopping = true;
103	    clearInterval(this.reaper);
104	    const waits = [];
105	    for (const child of this.children.values()) {
106	      waits.push(new Promise((resolve) => child.once('exit', resolve)));
107	      if (child.connected) child.send({ kind: STOP }, () => {});
108	    }
109	    const timer = setTimeout(() => {
110	      for (const child of this.children.values()) child.kill();
111	    }, STOP_GRACE_MS);
112	    await Promise.all(waits);
113	    clearTimeout(timer);
114	    this.queue?.close();
115	  }
116	}
