  const { queue, clock } = setup(t);
  queue.enqueue('x', null);
  const job = queue.claim('w', { leaseMs: 500 });
  clock.advance(400);
  queue.heartbeat(job.id, job.token, { leaseMs: 500 });
  clock.advance(400);
  assert.deepEqual(queue.reapExpired(), []);
  clock.advance(100);
  assert.equal(queue.reapExpired().length, 1);
