// A child that does one thing to the queue in argv[2] and is expected to be killed
// by a failpoint on the way. argv[3] picks what it does.

import { openQueue } from '../../src/index.mjs';

const [, , dir, action] = process.argv;
const queue = openQueue(dir, { backoff: { baseMs: 0 } });

switch (action) {
  case 'complete': {
    const job = queue.claim('child');
    queue.complete(job.id, job.token, { by: 'child' });
    break;
  }
  case 'claim':
    queue.claim('child');
    break;
  case 'compact':
    queue.compact();
    break;
  case 'enqueue':
    queue.enqueue('from-child', { pid: process.pid });
    break;
  case 'open':
    break;
  default:
    throw new Error(`unknown action ${action}`);
}
queue.close();

// Crashes and power cuts at every step of a write, checked against
// docs/guarantees.md. Each case runs a child that a failpoint kills, then looks at
// what the next process finds.

import assert from 'node:assert/strict';
import { fork } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';
import { fileURLToPath } from 'node:url';
import { CorruptLogError, ManualClock, openQueue } from '../src/index.mjs';
import { defer, tempDir } from './helpers/tmp.mjs';

const CHILD = fileURLToPath(new URL('./helpers/crash-child.mjs', import.meta.url));

function exitOf(child) {
  return new Promise((resolve) => child.on('exit', (code, signal) => resolve({ code, signal })));
}

/** Runs the child with a failpoint armed. Returns whether the failpoint fired. */
async function crash(t, dir, action, rules, { power = false } = {}) {
  const markers = tempDir(t);
  const env = { ...process.env, WALQ_FAILPOINTS: rules, WALQ_FAILPOINT_DIR: markers };
  if (power) env.WALQ_SIMULATE_POWER_LOSS = '1';
  const child = fork(CHILD, [dir, action], { env, silent: true });
  defer(t, () => child.kill());
  await exitOf(child);
  const name = rules.split('=')[0].replace('#', '.');
  return fs.existsSync(path.join(markers, `${name}.hit`));
}

const later = () => new ManualClock(Date.now() + 3_600_000);

for (const power of [false, true]) {
  const model = power ? 'power loss' : 'kill';

  // The crash table of RFC 007, point by point.
  for (const point of ['wal.before-append', 'wal.mid-append', 'wal.after-write', 'wal.after-fsync']) {
    test(`complete cut off at ${point} (${model})`, async (t) => {
      const dir = tempDir(t);
      const seeded = openQueue(dir);
      const { id } = seeded.enqueue('x', 1);
      seeded.close();

      assert.ok(await crash(t, dir, 'complete', `${point}#complete=kill`, { power }), 'failpoint fired');

      const queue = openQueue(dir, { clock: later(), backoff: { baseMs: 0 } });
      const committed = point === 'wal.after-fsync' || (point === 'wal.after-write' && !power);
      if (committed) {
        assert.equal(queue.getJob(id).status, 'done');
        assert.deepEqual(queue.reapExpired(), []);
        assert.equal(queue.claim('again'), null, 'a commit never leads to a rerun');
      } else {
        assert.equal(queue.getJob(id).status, 'leased');
        assert.equal(queue.reapExpired().length, 1);
        const again = queue.claim('again');
        assert.equal(again.id, id, 'an uncommitted job runs again');
        assert.equal(again.attempt, 2);
        queue.complete(again.id, again.token, 'ok');
      }

      // Nothing written afterwards may be affected by what was cut off (G3).
      queue.enqueue('x', 'after');
      queue.close();
      const reopened = openQueue(dir, { clock: later() });
      assert.equal(reopened.getJob(id).status, 'done');
      assert.equal(reopened.stats().total, 2);
    });
  }

  test(`enqueue cut off mid-append does not harm later writes (${model})`, async (t) => {
    const dir = tempDir(t);
    openQueue(dir).close();
    assert.ok(await crash(t, dir, 'enqueue', 'wal.mid-append=kill', { power }));
    for (let round = 0; round < 3; round += 1) {
      const queue = openQueue(dir);
      queue.enqueue('x', round);
      queue.close();
    }
    const queue = openQueue(dir);
    assert.deepEqual(queue.listJobs().map((j) => j.payload).filter((p) => typeof p === 'number'), [0, 1, 2]);
  });

  for (const point of ['compact.after-tmp-write', 'compact.before-rename', 'compact.after-rename']) {
    test(`compaction killed at ${point} loses nothing and can run again (${model})`, async (t) => {
      const dir = tempDir(t);
      const clock = new ManualClock(10_000);
      const seeded = openQueue(dir, { clock });
      for (let i = 0; i < 6; i += 1) seeded.enqueue('x', { i }, { key: `k${i}` });
      const job = seeded.claim('w');
      seeded.fail(job.id, job.token, 'oops');
      const before = seeded.listJobs();
      seeded.close();

      assert.ok(await crash(t, dir, 'compact', `${point}=kill`, { power }));

      const queue = openQueue(dir, { clock });
      assert.deepEqual(queue.listJobs(), before);
      queue.compact();
      assert.deepEqual(queue.listJobs(), before);
      queue.enqueue('x', 'more');
      queue.close();
      assert.equal(openQueue(dir, { clock }).stats().total, 7);
    });
  }
}

test('a log whose creation is cut off by a power loss still opens', async (t) => {
  const dir = tempDir(t);
  assert.ok(await crash(t, dir, 'open', 'wal.after-create=kill', { power: true }));
  const queue = openQueue(dir);
  queue.enqueue('x', 1);
  assert.equal(queue.stats().total, 1);
});

test('a compaction that keeps failing does not poison the next one', (t) => {
  const dir = tempDir(t);
  const queue = openQueue(dir);
  queue.enqueue('x', 1);
  // What a crashed compaction leaves behind.
  fs.writeFileSync(path.join(dir, 'wal.log.compact'), 'half a log');
  queue.compact();
  assert.equal(queue.stats().generation, 2);
  assert.ok(!fs.existsSync(path.join(dir, 'wal.log.compact')));
});

test('a failed compaction cleans up its temp file', (t) => {
  const dir = tempDir(t);
  const queue = openQueue(dir);
  queue.enqueue('x', 1);
  // Make the rename fail: a directory cannot be replaced by a file.
  const log = path.join(dir, 'wal.log');
  const keep = fs.readFileSync(log);
  const original = queue.store.ops.rename;
  queue.store.ops.rename = () => {
    const err = new Error('EPERM: operation not permitted, rename');
    err.code = 'EPERM';
    throw err;
  };
  assert.throws(() => queue.compact(), /compaction failed/);
  queue.store.ops.rename = original;
  assert.ok(!fs.existsSync(path.join(dir, 'wal.log.compact')));
  assert.deepEqual(fs.readFileSync(log), keep);
  queue.enqueue('x', 2);
  queue.compact();
  assert.equal(queue.stats().total, 2);
});

test('damage inside the log is reported with its offset and the file is left alone', (t) => {
  const dir = tempDir(t);
  const clock = new ManualClock(0);
  const queue = openQueue(dir, { clock });
  for (let i = 0; i < 5; i += 1) queue.enqueue('x', `payload ${i}`);
  queue.close();
  const log = path.join(dir, 'wal.log');
  const bytes = fs.readFileSync(log);
  bytes[bytes.length >> 1] ^= 0x55;
  fs.writeFileSync(log, bytes);
  assert.throws(
    () => openQueue(dir, { clock }),
    (err) => err instanceof CorruptLogError && Number.isInteger(err.offset),
  );
  assert.deepEqual(fs.readFileSync(log), bytes);
});

test('a log with trailing damage after good frames is reported, not trimmed', (t) => {
  const dir = tempDir(t);
  const queue = openQueue(dir);
  queue.enqueue('x', 1);
  queue.enqueue('x', 2);
  queue.close();
  const log = path.join(dir, 'wal.log');
  const bytes = fs.readFileSync(log);
  // Damage the first record's payload: the second record, which follows it, was acknowledged.
  bytes[40] ^= 0xff;
  fs.writeFileSync(log, bytes);
  assert.throws(() => openQueue(dir), CorruptLogError);
  assert.deepEqual(fs.readFileSync(log), bytes);
});

// Properties from docs/guarantees.md that only show up with several processes on
// one log, across restarts, or across compaction. Two Queue instances on one folder
// behave as two processes: each has its own state and takes the same lock.

import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { test } from 'node:test';
import { clearFailpoints, ManualClock, onFailpoint, openQueue, StaleLeaseError } from '../src/index.mjs';
import { tempDir } from './helpers/tmp.mjs';

const BACKOFF = { baseMs: 1_000, factor: 2, maxMs: 60_000 };

function pair(t, options = {}) {
  const clock = new ManualClock(1_000_000);
  const dir = tempDir(t);
  const settings = { clock, backoff: BACKOFF, ...options };
  t.after(clearFailpoints);
  return { clock, dir, a: openQueue(dir, settings), b: openQueue(dir, settings), settings };
}

/** Runs `action` once, the first time `name` is reached. */
function once(name, action) {
  let fired = false;
  onFailpoint(name, () => {
    if (fired) return;
    fired = true;
    action();
  });
}

test('G6: two workers racing for one job cannot both get it', (t) => {
  const { a, b } = pair(t);
  a.enqueue('x', 1);
  let theirs;
  once('claim.before-lock', () => {
    theirs = b.claim('b');
  });
  const mine = a.claim('a');
  assert.ok(theirs, 'the other process took it');
  assert.equal(mine, null, 'this one must notice and take nothing');
});

test('G6: racing claims on two jobs get different jobs and tokens', (t) => {
  const { a, b } = pair(t);
  a.enqueue('x', 1);
  a.enqueue('x', 2);
  let theirs;
  once('claim.before-lock', () => {
    theirs = b.claim('b');
  });
  const mine = a.claim('a');
  assert.notEqual(mine.id, theirs.id);
});

test('G6: a token is never issued twice for a job, even across requeue and compaction', (t) => {
  const { clock, a } = pair(t, { maxAttempts: 1 });
  const { id } = a.enqueue('x', 1);
  const tokens = [];
  for (let round = 0; round < 4; round += 1) {
    const job = a.claim('w');
    tokens.push(job.token);
    a.fail(job.id, job.token, 'no');
    assert.equal(a.getJob(id).status, 'dead');
    if (round % 2) a.compact();
    a.requeueDead(id);
    clock.advance(1);
  }
  assert.equal(new Set(tokens).size, tokens.length, `tokens ${tokens}`);
});

test('G8: an old token cannot touch the job', (t) => {
  const { clock, a } = pair(t);
  const { id } = a.enqueue('x', 1);
  const first = a.claim('w1');
  a.fail(first.id, first.token, 'no');
  clock.advance(5_000);
  const second = a.claim('w2');
  assert.equal(second.id, id);
  assert.throws(() => a.heartbeat(id, first.token), StaleLeaseError);
  assert.throws(() => a.complete(id, first.token, 'late'), StaleLeaseError);
  assert.throws(() => a.fail(id, first.token, 'late'), StaleLeaseError);
  assert.equal(a.getJob(id).status, 'leased');
  a.complete(id, second.token, 'fine');
});

test('G7: a heartbeat is seen by the process that runs the reaper', (t) => {
  const { clock, a, b } = pair(t);
  a.enqueue('x', 1);
  const job = a.claim('w', { leaseMs: 500 });
  clock.advance(400);
  a.heartbeat(job.id, job.token, { leaseMs: 500 });
  clock.advance(400);
  assert.deepEqual(b.reapExpired(), []);
  assert.equal(b.getJob(job.id).status, 'leased');
});

test('G7: a reaper that waited for the lock does not reap a lease renewed meanwhile', (t) => {
  const { clock, a, b } = pair(t);
  a.enqueue('x', 1);
  const job = a.claim('w', { leaseMs: 500 });
  clock.advance(500);
  once('reap.before-lock', () => a.heartbeat(job.id, job.token, { leaseMs: 500 }));
  assert.deepEqual(b.reapExpired(), []);
  assert.equal(a.getJob(job.id).status, 'leased');
});

test('G10: a key racing between two processes creates one job', (t) => {
  const { a, b } = pair(t);
  let theirs;
  once('enqueue.before-lock', () => {
    theirs = b.enqueue('x', 'b', { key: 'same' });
  });
  const mine = a.enqueue('x', 'a', { key: 'same' });
  assert.equal(theirs.deduped, false);
  assert.equal(mine.deduped, true);
  assert.equal(mine.id, theirs.id);
  assert.equal(a.stats().total, 1);
});

test('G10: a key is remembered after its job has been pruned and the log compacted', (t) => {
  const day = 24 * 60 * 60 * 1000;
  const { clock, dir, a, settings } = pair(t);
  const first = a.enqueue('report', 1, { key: 'report-2026-09' });
  const job = a.claim('w');
  a.complete(job.id, job.token, { sent: true });

  clock.advance(3 * day);
  a.compact();
  assert.equal(a.getJob(first.id), null, 'the job itself is gone');

  for (const queue of [a, openQueue(dir, settings)]) {
    const again = queue.enqueue('report', 2, { key: 'report-2026-09' });
    assert.equal(again.deduped, true);
    assert.equal(again.id, first.id);
    assert.equal(again.status, 'done');
    assert.deepEqual(again.result, { sent: true });
  }
  a.compact();
  a.compact();
  assert.equal(a.enqueue('report', 3, { key: 'report-2026-09' }).deduped, true);

  clock.advance(5 * day);
  assert.equal(a.enqueue('report', 4, { key: 'report-2026-09' }).deduped, false, 'past its time to live');
});

test('G9: a retry keeps its due time across a restart', (t) => {
  const { clock, dir, a, settings } = pair(t);
  const { id } = a.enqueue('x', 1);
  const job = a.claim('w');
  const { retryAt } = a.fail(job.id, job.token, 'no');
  assert.equal(retryAt, clock.now() + 1_000);
  a.close();

  clock.advance(500_000);
  const reopened = openQueue(dir, settings);
  assert.equal(reopened.getJob(id).availableAt, retryAt);
  assert.equal(reopened.claim('w').id, id, 'long overdue, so due now');

  clock.set(retryAt - 1);
  const early = openQueue(dir, { ...settings, clock });
  const { id: other } = early.enqueue('x', 2, { delayMs: 0 });
  early.getJob(other);
});

test('G9: every process sees the same due time', (t) => {
  const { clock, a, b } = pair(t);
  const { id } = a.enqueue('x', 1);
  const job = a.claim('w');
  a.fail(job.id, job.token, 'no');
  clock.advance(300);
  assert.equal(a.getJob(id).availableAt, b.getJob(id).availableAt);
  assert.equal(b.claim('b'), null);
});

test('G9: attempts and backoff carry through compaction, so maxAttempts holds', (t) => {
  const { clock, a } = pair(t, { maxAttempts: 4 });
  const { id } = a.enqueue('x', 1);
  const delays = [];
  for (let attempt = 1; attempt <= 4; attempt += 1) {
    clock.advance(100_000);
    const job = a.claim('w');
    assert.equal(job.attempt, attempt);
    const outcome = a.fail(job.id, job.token, 'no');
    if (outcome.status === 'ready') delays.push(outcome.retryAt - clock.now());
    a.compact();
  }
  assert.equal(a.getJob(id).status, 'dead');
  assert.deepEqual(delays, [1_000, 2_000, 4_000]);
});

test('G11: compaction changes no job field', (t) => {
  const { clock, a } = pair(t);
  a.enqueue('x', { n: 1 }, { priority: 5, maxAttempts: 7, key: 'k1' });
  a.enqueue('x', { n: 2 });
  const leased = a.claim('w', { leaseMs: 90_000 });
  const retried = a.claim('w');
  a.fail(retried.id, retried.token, 'oops');
  const done = a.enqueue('x', 3);
  const finished = a.claim('w2');
  assert.equal(finished.id, done.id);
  a.complete(finished.id, finished.token, 'r');
  a.enqueue('x', 4, { delayMs: 5_000 });
  a.cancel(a.enqueue('x', 5).id);
  clock.advance(10);

  const before = a.listJobs();
  assert.equal(leased.attempt, 1);
  a.compact();
  assert.deepEqual(a.listJobs(), before);
  a.close();
  assert.deepEqual(openQueue(a.dir, { clock, backoff: BACKOFF }).listJobs(), before);
});

test('G13: a process whose offset lies inside a larger new log follows the compaction', (t) => {
  const { a, b } = pair(t);
  for (let i = 0; i < 3; i += 1) a.enqueue('x', i);
  b.stats();
  const behind = b.store.offset;
  a.compact();
  assert.ok(a.store.offset > behind, 'the new log must be longer than where the other process stopped');
  assert.equal(b.stats().total, 3);
  assert.equal(b.enqueue('x', 'next').id, 'j4');
  assert.equal(a.stats().total, 4);
});

test('G13: a process far ahead of a smaller new log follows it too', (t) => {
  const { a, b } = pair(t, { compactAfterBytes: 0 });
  for (let i = 0; i < 50; i += 1) {
    const { id } = a.enqueue('x', i);
    const job = a.claim('w');
    a.complete(job.id, job.token, id);
  }
  b.stats();
  a.compact();
  assert.equal(b.stats().done, 50);
  a.enqueue('x', 'after');
  assert.equal(b.stats().ready, 1);
});

