  a.enqueue('x', 'small after it');
  assert.equal(b.getJob(id).payload.big.length, big.length, 'another process catches up over it');
  a.close();
  const reopened = openQueue(dir, settings);
  assert.equal(reopened.stats().total, 2);
  assert.equal(reopened.stats().tornTailsDropped, 0);
