test('G5: a log of many megabytes reopens whole, and ids are not reused', (t) => {
  const { dir, a, settings } = pair(t, { compactAfterBytes: 0 });
  const total = 6_000;
  const items = Array.from({ length: total }, (_, n) => ({ type: 'x', payload: { n, pad: 'p'.repeat(300) } }));
  for (let at = 0; at < total; at += 500) a.enqueueMany(items.slice(at, at + 500));
