test('old logs keep working: unknown records are ignored and old snapshots load', (t) => {
  const { dir, settings } = setup(t);
  // A snapshot as 0.4.x wrote it (no attempts, fence, priority or idem), then a
  // record type from some future writer.
  const old = {
    t: 'snapshot',
    at: 5,
    seq: 2,
    jobs: [
      { id: 'j1', type: 'x', payload: 1, key: 'k', status: 'done', maxAttempts: 5, availableAt: 0, lease: null, result: 'r', lastError: null, enqueuedAt: 1_000_000, completedAt: 1_000_001, seq: 1 },
      { id: 'j2', type: 'x', payload: 2, key: null, status: 'ready', maxAttempts: 5, availableAt: 0, lease: null, result: null, lastError: null, enqueuedAt: 1, completedAt: null, seq: 2 },
    ],
  };
  const file = path.join(dir, 'wal.log');
  const body = Buffer.concat([old, { t: 'future-record', id: 'j2', x: 1 }].map(encodeFrame));
  fs.writeFileSync(file, Buffer.concat([fs.readFileSync(file).subarray(0, 20), body]));

  const queue = openQueue(dir, settings);
  assert.equal(queue.getJob('j1').status, 'done');
  assert.equal(queue.getJob('j1').completionSeq, null);
  assert.deepEqual(queue.completions(), []);
  assert.equal(queue.enqueue('x', 3, { key: 'k' }).deduped, true);
  const job = queue.claim('w');
  assert.equal(job.id, 'j2');
  assert.equal(job.token, 1);
  assert.equal(queue.complete(job.id, job.token, 'ok').completionSeq, 1, 'numbering starts after the old ones');
});

